import React from 'react';
import { ArrowLeft, ArrowRight, Play, CheckCircle2 } from 'lucide-react';
import { HIDDEN_PORTFOLIO_IDS } from '../config';
import { PORTFOLIO_PROJECTS } from '../data/portfolioData';
import { TRANSLATIONS } from '../data/translations';
import { Language, MediaAsset, PortfolioProject } from '../types';

interface ProjectDetailViewProps {
  projectId: string;
  language: Language;
  onNavigate: (view: string, projectId?: string) => void;
  onOpenLightbox: (asset: MediaAsset, projectGallery: MediaAsset[]) => void;
  onOpenVideo: (project: PortfolioProject) => void;
}

export const ProjectDetailView: React.FC<ProjectDetailViewProps> = ({
  projectId,
  language,
  onNavigate,
  onOpenLightbox,
  onOpenVideo
}) => {
  const t = TRANSLATIONS[language];
  const isSv = language === 'sv';
  const visibleProjects = PORTFOLIO_PROJECTS.filter((p) => !HIDDEN_PORTFOLIO_IDS.has(p.id));
  const foundIndex = visibleProjects.findIndex((p) => p.id === projectId || p.slug === projectId);
  const projectIndex = foundIndex !== -1 ? foundIndex : 0;
  const project = visibleProjects[projectIndex] || PORTFOLIO_PROJECTS[0];

  const nextProject = visibleProjects[(projectIndex + 1) % visibleProjects.length];
  const isFilm = project.discipline === 'film_live';
  const isVerticalVideo = isFilm && project.coverAsset.aspectRatio === '9:16';
  const allMedia = [project.coverAsset, ...project.gallery];
  const roles = isSv ? project.rolesSv : project.rolesEn;
  const deliverables = isSv ? project.deliverablesSv : project.deliverablesEn;
  const relationshipLabel = isSv ? project.relationshipLabelSv : project.relationshipLabelEn;

  return (
    <article
      className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 sm:py-20 space-y-20"
    >
      {/* Top Minimal Back Navigation */}
      <div className="flex flex-wrap items-center justify-between gap-4 text-xs font-mono text-white/60">
        <button
          onClick={() => {
            onNavigate('work');
            window.scrollTo({ top: 0, behavior: 'smooth' });
          }}
          className="hover:text-white flex items-center gap-2 transition-colors cursor-pointer"
        >
          <ArrowLeft className="w-4 h-4" />
          <span>{t.project.backToWork}</span>
        </button>

        <div className="flex items-center gap-3">
          <span className="text-white font-bold">
            {String(projectIndex + 1).padStart(2, '0')} / {visibleProjects.length}
          </span>
          <span aria-hidden="true">·</span>
          <span className="uppercase">{project.coverAsset.aspectRatio}</span>
        </div>
      </div>

      {/* Project Header */}
      <div className="space-y-6 max-w-4xl">
        <div className="flex flex-wrap items-center gap-3 text-xs font-mono text-[#f59e0b] uppercase tracking-widest">
          {relationshipLabel && (
            <>
              <span className="px-2.5 py-1 rounded-full bg-[#f59e0b]/15 border border-[#f59e0b]/30 text-[#f59e0b] font-semibold">
                {relationshipLabel}
              </span>
              <span aria-hidden="true">·</span>
            </>
          )}
          <span>{project.clientOrSubject}</span>
          <span aria-hidden="true">·</span>
          <span>{project.location}</span>
          <span aria-hidden="true">·</span>
          <span>{project.year}</span>
        </div>

        <h1 className="font-display text-4xl sm:text-6xl font-black tracking-tight text-white leading-[1.02]">
          {project.title}
        </h1>

        <p className="text-base sm:text-xl text-[#b0b4be] leading-relaxed font-light max-w-3xl">
          {language === 'en' ? project.narrativeEn : project.narrativeSv}
        </p>

        {/* Project Scope: Role & Execution + Deliverables */}
        {(roles.length > 0 || deliverables.length > 0) && (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 pt-6 mt-6 border-t border-white/10">
            {roles.length > 0 && (
              <div className="space-y-2.5">
                <h2 className="text-xs font-mono uppercase tracking-widest text-white/65">
                  {t.project.rolesTitle}
                </h2>
                <ul className="space-y-1.5 text-sm text-white/85">
                  {roles.map((role) => (
                    <li key={role} className="flex items-start gap-2">
                      <CheckCircle2 className="w-4 h-4 text-[#f59e0b] shrink-0 mt-0.5" />
                      <span>{role}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {deliverables.length > 0 && (
              <div className="space-y-2.5">
                <h2 className="text-xs font-mono uppercase tracking-widest text-white/65">
                  {t.project.deliverablesTitle}
                </h2>
                <ul className="space-y-1.5 text-sm text-white/85">
                  {deliverables.map((item) => (
                    <li key={item} className="flex items-start gap-2">
                      <span className="text-[#f59e0b] font-mono text-xs mt-0.5">—</span>
                      <span>{item}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {project.relationshipType === 'press_accreditation' && (
              <p className="sm:col-span-2 text-xs font-mono text-white/65 pt-1">
                {isSv
                  ? 'Notering: Redaktionell bevakning / pressackreditering. Eventets eller organisationens namn anger motiv och plats.'
                  : 'Note: Editorial coverage / press accreditation. The event or organisation name identifies the subject and venue.'}
              </p>
            )}
          </div>
        )}
      </div>

      {/* Main Lead Media — Frameless, Exact Native Aspect Ratio */}
      <div className="w-full" data-protected-media="true">
        {isFilm ? (
          <div
            className={`relative overflow-hidden rounded-3xl ${
              isVerticalVideo ? 'max-w-md mx-auto' : 'w-full'
            }`}
          >
            {project.externalVideoUrl ? (
              <video
                key={project.externalVideoUrl}
                src={project.externalVideoUrl}
                poster={project.coverAsset.url}
                controls
                controlsList="nodownload noplaybackrate"
                disablePictureInPicture
                playsInline
                onContextMenu={(e) => e.preventDefault()}
                className="w-full h-auto block rounded-3xl shadow-2xl select-none"
              />
            ) : (
              <div
                onClick={() => onOpenVideo(project)}
                className="relative cursor-pointer group"
              >
                <img
                  src={project.coverAsset.url}
                  alt={`${project.title} – photo by Dino / Dino Studio`}
                  draggable={false}
                  onContextMenu={(e) => e.preventDefault()}
                  className="w-full h-auto block rounded-3xl shadow-2xl select-none"
                />
                <div className="absolute inset-0 flex items-center justify-center">
                  <div className="w-16 h-16 rounded-full bg-white text-black flex items-center justify-center shadow-2xl">
                    <Play className="w-6 h-6 fill-current ml-1" />
                  </div>
                </div>
              </div>
            )}
          </div>
        ) : (
          <div
            onClick={() => onOpenLightbox(project.coverAsset, allMedia)}
            tabIndex={0}
            role="button"
            aria-label={project.title}
            onKeyDown={(e) => {
              if (e.target === e.currentTarget && (e.key === 'Enter' || e.key === ' ')) {
                e.preventDefault();
                onOpenLightbox(project.coverAsset, allMedia);
              }
            }}
            className={`cursor-pointer overflow-hidden rounded-3xl ${
              project.coverAsset.aspectRatio === '2:3' ||
              project.coverAsset.aspectRatio === '3:4'
                ? 'max-w-3xl'
                : 'w-full'
            }`}
          >
            <img
              src={project.coverAsset.url}
              alt={`${project.title} – photo by Dino / Dino Studio`}
              draggable={false}
              onContextMenu={(e) => e.preventDefault()}
              className="w-full h-auto block rounded-3xl shadow-2xl hover:scale-[1.01] transition-transform duration-700 select-none"
            />
          </div>
        )}
      </div>

      {/* Frameless Gallery of All Photographs in Their Exact Original Proportions */}
      {project.gallery.length > 0 && (
        <div className="space-y-12 pt-8">
          <div className="flex items-center justify-between border-b border-white/10 pb-4">
            <span className="text-xs font-mono uppercase tracking-widest text-white/65">
              {language === 'en'
                ? `SERIES ARCHIVE (${project.gallery.length} PHOTOGRAPHS · CLICK ANY FRAME TO INSPECT)`
                : `BILDSERIE (${project.gallery.length} FOTOGRAFIER · KLICKA FÖR FULLSKÄRM)`}
            </span>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-12 gap-y-16 md:gap-x-12 items-start">
            {project.gallery.map((item, idx) => {
              const isVertical =
                item.aspectRatio === '2:3' ||
                item.aspectRatio === '3:4' ||
                item.aspectRatio === '9:16';

              const spanClass = isVertical
                ? idx % 2 === 0
                  ? 'md:col-span-5'
                  : 'md:col-span-5 md:col-start-7 md:mt-16'
                : idx % 2 === 0
                  ? 'md:col-span-7'
                  : 'md:col-span-6 md:col-start-7 md:mt-12';

              return (
                <div
                  key={item.id}
                  onClick={() => onOpenLightbox(item, allMedia)}
                  tabIndex={0}
                  role="button"
                  aria-label={`${project.title} — ${language === 'en' ? item.titleEn : item.titleSv}`}
                  onKeyDown={(e) => {
                    if (e.target === e.currentTarget && (e.key === 'Enter' || e.key === ' ')) {
                      e.preventDefault();
                      onOpenLightbox(item, allMedia);
                    }
                  }}
                  className={`group cursor-pointer space-y-3 ${spanClass}`}
                  data-protected-media="true"
                >
                  <div className="overflow-hidden rounded-2xl">
                    <img
                      src={item.url}
                      alt={`${project.title} (${language === 'en' ? item.titleEn : item.titleSv}) – photo by Dino / Dino Studio`}
                      draggable={false}
                      onContextMenu={(e) => e.preventDefault()}
                      loading="lazy"
                      className="w-full h-auto block rounded-2xl transition-transform duration-700 group-hover:scale-[1.02] select-none"
                    />
                  </div>
                  <div className="flex items-center justify-between text-[11px] font-mono text-white/60 px-1">
                    <span>{String(idx + 2).padStart(2, '0')}</span>
                    <span>{item.aspectRatio}</span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Project Enquiry / Conversion Card */}
      <div className="bg-white/[0.03] border border-white/10 rounded-3xl p-6 sm:p-10 flex flex-col sm:flex-row sm:items-center justify-between gap-6">
        <div className="space-y-2 max-w-2xl">
          <span className="text-xs font-mono uppercase tracking-widest text-[#f59e0b] block">
            DINO STUDIO · STOCKHOLM
          </span>
          <h2 className="font-display text-2xl sm:text-3xl font-bold text-white">
            {t.home.ctaBannerTitle}
          </h2>
          <p className="text-sm sm:text-base text-[#b0b4be] font-light leading-relaxed">
            {t.home.ctaBannerDesc}
          </p>
        </div>

        <button
          onClick={() => {
            onNavigate('contact');
            window.scrollTo({ top: 0, behavior: 'smooth' });
          }}
          className="px-7 py-4 bg-white text-black hover:bg-neutral-200 rounded-full font-mono text-xs font-bold uppercase tracking-widest transition-colors cursor-pointer flex items-center gap-2 shrink-0 self-start sm:self-center"
        >
          <span>{t.hero.ctaContact}</span>
          <ArrowRight className="w-4 h-4" />
        </button>
      </div>

      {/* Next Project Navigation */}
      <div className="pt-16 border-t border-white/10 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-6">
        <div className="space-y-1">
          <span className="text-xs font-mono uppercase tracking-widest text-white/65 block">
            {t.project.nextProject}
          </span>
          <h3 className="font-display text-2xl sm:text-4xl font-black text-white">
            {nextProject.title}
          </h3>
        </div>

        <button
          onClick={() => {
            onNavigate('project', nextProject.id);
            window.scrollTo({ top: 0, behavior: 'smooth' });
          }}
          className="px-7 py-4 bg-white text-black hover:bg-neutral-200 rounded-full font-mono text-xs font-bold uppercase tracking-widest transition-colors cursor-pointer flex items-center gap-2"
        >
          <span>{language === 'en' ? 'Next Work' : 'Nästa Arbete'}</span>
          <ArrowRight className="w-4 h-4" />
        </button>
      </div>
    </article>
  );
};
